'use strict'
const assert = require('assert')
const Bloxd = require('../assets/js/bloxd-schematic.js')

// Independent minimal decoder used only to verify generated bytes.
function decode(bytes) {
  let offset = 0
  function uvarint() {
    let result = 0, multiplier = 1
    while (true) {
      const byte = bytes[offset++]
      result += (byte & 127) * multiplier
      if (!(byte & 128)) return result
      multiplier *= 128
    }
  }
  function avroInt() { const n = uvarint(); return n % 2 ? -(n + 1) / 2 : n / 2 }
  function raw() { const length = avroInt(); const value = bytes.slice(offset, offset + length); offset += length; return value }
  function string() { return new TextDecoder().decode(raw()) }
  assert.deepStrictEqual(Array.from(bytes.slice(0, 4)), [0, 0, 0, 0]); offset = 4
  const result = { name: string(), origin: [avroInt(), avroInt(), avroInt()], size: [avroInt(), avroInt(), avroInt()], chunks: [] }
  while (true) {
    let count = avroInt()
    if (!count) break
    if (count < 0) { count = -count; avroInt() }
    for (let i = 0; i < count; i++) {
      const position = [avroInt(), avroInt(), avroInt()]
      const rle = raw(), blocks = new Int32Array(32768)
      let r = 0, write = 0
      function rleUvarint() { let n = 0, m = 1; while (true) { const b = rle[r++]; n += (b & 127) * m; if (!(b & 128)) return n; m *= 128 } }
      while (r < rle.length) { const run = rleUvarint(), id = rleUvarint(); blocks.fill(id, write, write + run); write += run }
      assert.strictEqual(write, 32768)
      result.chunks.push({ position, blocks })
    }
  }
  assert.strictEqual(offset, bytes.length)
  return result
}

const voxels = new Map([
  ['-3,-2,5', 28],
  ['28,-2,5', 65],
  ['29,-2,5', 172],
  ['62,31,36', 106]
])
const encoded = Bloxd.encodeSchematic(voxels, 'Round trip ✓')
const decoded = decode(encoded.bytes)
assert.strictEqual(decoded.name, 'Round trip ✓')
assert.deepStrictEqual(decoded.origin, [0, 0, 0])
assert.deepStrictEqual(decoded.size, [96, 64, 32])
assert.strictEqual(encoded.totalChunks, 6)
assert.strictEqual(decoded.chunks.length, 6)
function get(x, y, z) {
  const chunk = decoded.chunks.find(item => item.position[0] === Math.floor(x / 32) && item.position[1] === Math.floor(y / 32) && item.position[2] === Math.floor(z / 32))
  return chunk.blocks[(x % 32) * 1024 + (y % 32) * 32 + (z % 32)]
}
assert.strictEqual(get(0, 0, 0), 28)
assert.strictEqual(get(31, 0, 0), 65)
assert.strictEqual(get(32, 0, 0), 172)
assert.strictEqual(get(65, 33, 31), 106)
assert.strictEqual(get(10, 10, 10), 0)
assert.throws(() => Bloxd.encodeSchematic(new Map(), 'Empty'), /empty/i)
console.log(`Bloxd round trip passed: ${encoded.blockCount} blocks, ${encoded.totalChunks} chunks, ${encoded.bytes.length} bytes`)
